import React from 'react';

const DonorCard = ({ donor, onClick }) => {
    // Define background and border styling based on donor status
    let statusClass = '';
    let statusText = '';
    
    if (donor.status === 'pending') {
        statusClass = 'bg-yellow-100 text-yellow-800 border-yellow-300';
        statusText = 'Pending';
    } else if (donor.status === 'sending') {
        statusClass = 'bg-blue-100 text-blue-800 border-blue-300';
        statusText = 'Processing';
    } else {
        statusClass = 'bg-green-100 text-green-800 border-green-300';
        statusText = 'Completed';
    }
    
    // Define type class
    const typeClass = donor.type === 'sheep' 
        ? 'bg-sky-100 text-sky-800 border-sky-300'
        : 'bg-purple-100 text-purple-800 border-purple-300';
    
    // Beautiful card background based on status
    let cardBg = '';
    if (donor.status === 'pending') {
        cardBg = 'bg-gradient-to-r from-yellow-50 to-amber-50 border-l-4 border-yellow-400';
    } else if (donor.status === 'sending') {
        cardBg = 'bg-gradient-to-r from-blue-50 to-sky-50 border-l-4 border-blue-400';
    } else {
        cardBg = 'bg-gradient-to-r from-green-50 to-emerald-50 border-l-4 border-green-400';
    }

    return (
        <div 
            className={`p-4 mb-4 rounded-lg shadow-sm hover:shadow-md transition-all duration-300 cursor-pointer ${cardBg} relative overflow-hidden`}
            onClick={onClick}
        >
            {/* Keep original layout structure */}
            <div className="flex justify-between items-center">
                <div>
                    <h3 className="font-medium text-gray-800">{donor.firstName} {donor.lastName}</h3>
                    <p className="text-sm text-gray-600">{donor.whatsappNumber}</p>
                    <div className="flex mt-2 gap-2">
                        <span className={`text-xs px-2 py-1 rounded-full ${typeClass} border`}>
                            {donor.type === 'sheep' ? 'Sheep' : 'Cow (1/7 share)'}
                        </span>
                        <span className={`text-xs px-2 py-1 rounded-full ${statusClass} border`}>
                            {statusText}
                        </span>
                    </div>
                </div>
                <div className="text-right">
                    <p className="font-bold text-gray-900">{donor.price?.toLocaleString()} DA</p>
                    <p className="text-xs text-gray-500">{new Date(donor.createdAt).toLocaleDateString()}</p>
                </div>
            </div>

            {/* Add decorative elements */}
            <div className="absolute top-0 right-0 opacity-10 transform translate-x-1/3 -translate-y-1/3">
                {donor.type === 'sheep' ? (
                    <span className="text-6xl">🐑</span>
                ) : (
                    <span className="text-6xl">🐄</span>
                )}
            </div>
            
            <div className="absolute bottom-0 left-0 w-24 h-24 rounded-full opacity-10 bg-gradient-to-br from-indigo-200 to-purple-200 -mb-12 -ml-12"></div>
        </div>
    );
};

export default DonorCard;
